      // To remove plugins, remove it here and run `yarn test tests/js/babel-plugins` to verify

      "doExpressions",
      "classProperties",
      "exportDefaultFrom",
      "functionBind",
      "functionSent",
      "classPrivateProperties",
      "throwExpressions",
      "classPrivateMethods",
      "v8intrinsic",
      "partialApplication",
      ["decorators", { decoratorsBeforeExport: false }],
      "privateIn",
      "importAssertions",
      ["recordAndTuple", { syntaxType: "hash" }],
      "decimal",
      "moduleStringNames",
      "classStaticBlock",
      ...extraPlugins,
